import {generate} from './engine.js';
import {days,short,defaults,dateKey,addDays,monday,dayDiff,formatDate,clock,timeLabel,hours,loadState,validateBackup} from './data.js';
import {icon} from './icons.js';
import {prepareWeek,layoutOverlaps,focusRemaining} from './planning.js';
import {createPlanPDF} from './pdf-export.js';
import {parseCSV,parseTime,parseMatrix,parseTerm,parseCalendar,detectMatrix} from './imports.js';
const $=s=>document.querySelector(s),$$=s=>[...document.querySelectorAll(s)];
const esc=x=>String(x??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const button=(action,label,ico,cls='btn',extra='')=>`<button class="${cls}" data-action="${action}" ${label&&!extra.includes('aria-label')?'aria-label="'+esc(label)+'"':''} ${extra}>${ico?icon(ico):''}<span>${label}</span></button>`;
const state=loadState();
const today=dateKey(),initialWeek=monday(addDays(today,new Date(today+'T12:00:00Z').getUTCDay()===0?1:0));
let week=initialWeek,view='week',layout='week',selected=null,selectedDay=0,snapshot=null,filter=new Set(['corps','class','study','personal']),taskFilter='open',plan,weekTasks=[],hard=[],timer=state.focusSession||null,timerInterval=null,undo=null,saveFailed=false;
function persist(){try{localStorage.setItem('palette-v2',JSON.stringify(state));saveFailed=false;return true;}catch{saveFailed=true;notify('Changes are only in memory. Browser storage is full; download a backup from Sources.');return false;}}
function refresh(){
 if(snapshot){plan=snapshot.plan;weekTasks=snapshot.tasks;hard=snapshot.hard||plan.blocks.filter(b=>b.hard);return;}
 const input=prepareWeek(state,week);weekTasks=input.tasks;hard=input.hard;
 plan=generate(hard,weekTasks,state.prefs,state.locked.filter(b=>b.week===week),{notBefore:input.notBefore});
}
function update(msg){snapshot=null;refresh();persist();render();if(msg)notify(msg);}
function notify(message,undoFn){if(saveFailed)message='Changes are only in memory. Browser storage is full; download a backup from Sources.';undo=undoFn||null;$('#toast').innerHTML=`${icon('check')}<span>${esc(message)}</span>${undo?'<button data-action="undo">Undo</button>':''}`;$('#toast').className='toast show';clearTimeout(window.toastTimeout);window.toastTimeout=setTimeout(()=>$('#toast').classList.remove('show'),6000);}
function range(key=week){return `${formatDate(key,{month:'short',day:'numeric'})} – ${formatDate(addDays(key,6),{month:'short',day:'numeric'})}`;}
function stats(){const study=plan.blocks.filter(b=>!b.hard).reduce((s,b)=>s+b.end-b.start,0),demand=weekTasks.filter(t=>!t.done).reduce((s,t)=>s+t.minutes,0);return {study,demand,pct:demand?Math.min(100,Math.round(study/demand*100)):100,issues:plan.conflicts.length+(plan.violations?.length||0),fixed:hard.reduce((s,b)=>s+b.end-b.start,0)};}
const navItems=[['week','calendar','My week'],['tasks','tasks','Assignments'],['sources','sources','Sources'],['preferences','settings','Preferences'],['archive','archive','Plan archive']];
function miniCalendar(){const first=week.slice(0,7)+'-01',offset=(new Date(first+'T12:00:00Z').getUTCDay()+6)%7;return `<div class="rail-mini"><div class="mini-heading"><span>${formatDate(week,{month:'long',year:'numeric'})}</span>${icon('calendar')}</div><div class="mini-grid">${['M','T','W','T','F','S','S'].map(d=>`<span class="mini-day">${d}</span>`).join('')}${Array.from({length:42},(_,i)=>{const key=addDays(first,i-offset);return `<button data-date="${key}" aria-label="Open week of ${key}" class="${key>=week&&key<addDays(week,7)?'in-week':''} ${key===today?'is-date':''}" style="${key.slice(5,7)!==first.slice(5,7)?'opacity:.25':''}">${Number(key.slice(-2))}</button>`}).join('')}</div></div>`;}
function render(){const calendarScroll=$('.calendar-scroll')?.scrollTop||0,active=document.activeElement,activeKey=active?.dataset?.action?`[data-action="${CSS.escape(active.dataset.action)}"]`:active?.dataset?.complete?`[data-complete="${CSS.escape(active.dataset.complete)}"]`:null;const s=stats(),titles={week:'Your week. <em>Under control.</em>',tasks:'One thing. <em>Then the next.</em>',sources:'Everything <em>starts here.</em>',preferences:'Protect your <em>own rhythm.</em>',archive:'A record of <em>moving forward.</em>'};
 $('#app').innerHTML=`<div class="app-shell"><aside class="rail"><div class="brand"><span class="brand-mark">p</span><span class="brand-text">palette.</span></div><span class="brand-label">MAKE SPACE</span><div class="rail-divider"></div><div class="rail-label">WORKSPACE</div><nav aria-label="Main navigation">${navItems.map(([id,ico,label])=>`<button data-view="${id}" class="${view===id?'active':''}" title="${label}" ${view===id?'aria-current="page"':''}>${icon(ico)}<span>${label}</span>${id==='tasks'?`<b class="nav-count">${state.tasks.filter(t=>!t.done).length.toString().padStart(2,'0')}</b>`:''}</button>`).join('')}</nav>${miniCalendar()}<div class="rail-bottom"><div class="rail-quote">${icon('leaf')}<p>Structure for the work.<br>Space for the rest.</p><small>ONE WEEK AT A TIME</small></div><div class="profile"><span class="avatar">P</span><div><b>Your workspace</b><small>Your personal workspace</small></div></div></div></aside><main class="main"><header class="topbar"><div class="breadcrumbs">Workspace ${icon('right')} <strong>${navItems.find(n=>n[0]===view)?.[2]}</strong></div><div class="top-actions"><span class="local-status">${icon('shield')} ${saveFailed?'UNSAVED CHANGES':'SAVED ON THIS DEVICE'}</span><button class="search-btn" data-action="search" aria-label="Search assignments and commands">${icon('search')}<span>Quick find</span><kbd class="kbd">Ctrl K</kbd></button></div></header><div class="content"><div class="heading"><div><div class="eyebrow">${view==='week'?`YOUR WEEKLY CANVAS / ${formatDate(week,{month:'long',year:'numeric'}).toUpperCase()}`:'PALETTE / '+navItems.find(n=>n[0]===view)?.[2].toUpperCase()}</div><h1>${titles[view]}</h1><p class="sub">${{week:'A place for every commitment. A little room for you.',tasks:'Turn your deadlines into a plan you can actually follow.',sources:'Your commitments, classes, and deadlines. Brought together.',preferences:'A good plan respects your time and your limits.',archive:'Your plans, exactly as you saved them.'}[view]}</p></div><div class="heading-actions">${view==='week'?`${button('print','Export week','download')}${snapshot?'':button('regenerate','Regenerate','spark','btn primary')}`:view==='tasks'?button('new-task','Add assignment','plus','btn primary'):''}</div></div>${snapshot?`<div class="snapshot-banner"><span>${icon('archive')} &nbsp; Saved snapshot · ${esc(snapshot.date||range())} · Read only</span>${button('exit-snapshot','Back to live plan','arrow','btn small')}</div>`:''}${view==='week'?weekView(s):view==='tasks'?tasksView():view==='sources'?sourcesView():view==='preferences'?prefsView():archiveView()}<footer class="document-footer"><span>Palette / Designed around your real life</span><span>${snapshot?'ARCHIVED PLAN':state.sources.matrix?.startsWith('Sample')?'SAMPLE SCHEDULE · LOCAL EDITION':'LOCAL WORKSPACE'} / EASTERN TIME</span></footer></div></main></div>`;
 const scroller=$('.calendar-scroll');if(scroller)scroller.scrollTop=calendarScroll;if(activeKey)$(activeKey)?.focus({preventScroll:true});renderFocusDock();
}
function weekView(s){return `<section class="week-summary" aria-label="Weekly summary">${[['calendar',hours(s.fixed),'hrs','Fixed commitments'],['spark',hours(s.study),'hrs','Focused study planned'],['tasks',weekTasks.filter(t=>!t.done).length,'due','Assignments to plan'],['leaf',s.pct,'%','Study effort placed']].map(([ico,num,unit,label],i)=>`<div class="metric"><span class="metric-icon ${i===2?'amber':''}">${icon(ico)}</span><div><div class="metric-value">${num}<small>${unit}</small></div><div class="metric-name">${label}</div></div></div>`).join('')}</section><div class="planner-layout"><section class="calendar-pane">${weekContext()}<div class="calendar-toolbar"><div class="date-control">${button('prev','','left','icon-btn','aria-label="Previous week"')}<h2>${range()}</h2>${button('next','','right','icon-btn','aria-label="Next week"')}${button('today','Today',null,'btn ghost small')}</div><div class="toggle" aria-label="Calendar layout">${button('week-layout','Week','grid',layout==='week'?'active':'')}${button('agenda-layout','Agenda','tasks',layout==='agenda'?'active':'')}</div></div><div class="filter-bar"><div class="filters">${[['corps','Corps'],['class','Academics'],['study','Study'],['personal','Personal']].map(([k,l])=>`<button class="filter ${k} ${filter.has(k)?'':'off'}" data-filter="${k}" aria-pressed="${filter.has(k)}"><i class="swatch"></i>${l}</button>`).join('')}</div><span class="muted" style="font-size:10px">┊ Flexible study blocks</span></div><div class="desktop-calendar">${layout==='week'?calendar():agenda()}</div><div class="mobile-agenda"><div class="day-tabs">${short.map((d,i)=>`<button data-day="${i}" class="${selectedDay===i?'active':''}">${d}<b>${Number(addDays(week,i).slice(-2))}</b></button>`).join('')}</div>${agenda(selectedDay)}</div><div class="calendar-footer"><span>${icon('lock')}${plan.blocks.filter(b=>b.locked).length} locked · ${snapshot?'Snapshot preserved':'Changes save automatically'}</span>${snapshot?'':button('save-plan','Save snapshot','archive','text-btn')}</div></section><aside class="cockpit">${selected?detailCard():forecast(s)}${taskPanel()}${s.issues?conflictCard(s.issues):''}${plan.unplaced.length?`<div class="conflict-card">${icon('clock')}<div><b>${hours(plan.unplaced.reduce((a,b)=>a+b.minutes,0))} hours still need a place</b><p>Your deadlines and available time don’t quite line up.</p>${button('conflicts','Review unplaced work','arrow','')}</div></div>`:''}${workloadChart()}</aside></div>${printView()}`;}
function visibleBlocks(day){return plan.blocks.filter(b=>(day===undefined||b.day===day)&&filter.has(b.kind)).sort((a,b)=>a.start-b.start||a.end-b.end);}
function calendar(){const overlapLayout=layoutOverlaps(visibleBlocks());const gridStart=Math.min(360,...plan.blocks.map(b=>Math.floor(b.start/60)*60)),gridEnd=Math.max(1380,...plan.blocks.map(b=>Math.ceil(b.end/60)*60));return `<div class="calendar-wrap"><div class="calendar-scroll"><div class="week-grid"><div class="day-headers"><div class="timezone">ET</div>${days.map((d,i)=>{const load=plan.blocks.filter(b=>b.day===i).reduce((s,b)=>s+b.end-b.start,0);return `<button class="day-header ${selectedDay===i?'selected-day':''}" data-day="${i}" aria-label="Select ${d}"><span class="dow">${short[i]}</span><br><span class="day-num">${Number(addDays(week,i).slice(-2))}</span><span class="day-load">${Array.from({length:5},(_,j)=>`<i class="${j<Math.ceil(load/90)?'filled':''}"></i>`).join('')}</span></button>`}).join('')}</div><div class="grid-body" style="height:${(gridEnd-gridStart)*1.2}px"><div class="time-axis">${Array.from({length:(gridEnd-gridStart)/60},(_,i)=>`<span class="time" style="top:${i*72}px">${String(i+gridStart/60).padStart(2,'0')}:00</span>`).join('')}</div>${days.map((d,i)=>`<div class="day-column ${i>4?'weekend':''}">${visibleBlocks(i).map(b=>{const pos=overlapLayout.get(b.id)||{lane:0,lanes:1},lane=pos.lane,width=100/pos.lanes;return `<button class="event ${b.kind} ${selected===b.id?'selected':''} ${b.end-b.start<40?'compact':''}" data-block="${esc(b.id)}" style="top:${(b.start-gridStart)*1.2}px;height:${Math.max(25,(b.end-b.start)*1.2-3)}px;${pos.lanes>1?`left:calc(${lane*width}% + 3px);width:calc(${width}% - 5px);right:auto;`:''}" title="${esc(b.title)} · ${clock(b.start)}–${clock(b.end)}"><b>${b.locked?icon('lock'):''}${esc(b.title)}</b>${b.end-b.start>=40?`<small>${clock(b.start)}–${clock(b.end)}</small>`:''}${b.end-b.start>=65?`<span class="event-footer">${esc(b.course||b.location||'Time for you')}</span>`:''}</button>`}).join('')}</div>`).join('')}</div></div></div></div>`;}
function agenda(day){const indexes=day===undefined?[0,1,2,3,4,5,6]:[day];return `<div class="agenda">${indexes.map(i=>`<div class="agenda-day"><div class="agenda-day-head"><b>${Number(addDays(week,i).slice(-2))}</b><div><h3>${days[i]}</h3><span>${visibleBlocks(i).length} blocks · ${hours(visibleBlocks(i).reduce((s,b)=>s+b.end-b.start,0))} hours planned</span></div></div>${visibleBlocks(i).map(b=>`<button class="agenda-item ${b.kind}" data-block="${esc(b.id)}"><time>${clock(b.start)}<br>${clock(b.end)}</time><i></i><div><b>${esc(b.title)}</b><small>${esc(b.course||b.location||'Personal time')} · ${b.hard?'Fixed':b.locked?'Locked':'Flexible'}</small></div>${icon(b.locked?'lock':'right')}</button>`).join('')||'<div class="empty"><p>A little open space. Keep it yours.</p></div>'}</div>`).join('')}</div>`;}
function forecast(s){const crowded=s.issues||plan.unplaced.length;return `<section class="forecast"><div class="forecast-top"><span>THE WEEK AHEAD</span>${icon('spark')}</div><h2>${plan.unplaced.length?'Make a little<br><em>more room.</em>':'Your work has<br><em>room to land.</em>'}</h2><p>${s.demand?`${hours(s.study)} hours of study placed around your commitments. ${crowded?'A few details need your attention below.':'Your deadlines have breathing room.'}`:'No open assignments in this planning window. Add your next deadline whenever you’re ready.'}</p><div class="forecast-meter">${Array.from({length:20},(_,i)=>`<i class="${i<s.pct/5?'on':''}"></i>`).join('')}</div><div class="forecast-bottom"><span>STUDY COVERAGE</span><strong>${s.pct}% PLACED</strong></div></section>`;}
function detailCard(){const b=plan.blocks.find(x=>x.id===selected);if(!b){selected=null;return forecast(stats());}return `<section class="panel detail-card ${b.kind}">${button('close-detail','','close','icon-btn detail-close','aria-label="Close block details"')}<span class="pill ${b.kind==='corps'?'amber':''}">${icon(b.hard?'lock':'spark')}${b.hard?'Fixed commitment':b.locked?'Locked study':'Flexible study'}</span><h2>${esc(b.title)}</h2>${b.taskId&&weekTasks.find(t=>t.id===b.taskId)?.notes?`<p class="block-notes">${esc(weekTasks.find(t=>t.id===b.taskId).notes)}</p>`:''}<div class="detail-row">${icon('calendar')}${days[b.day]}, ${formatDate(addDays(week,b.day),{month:'short',day:'numeric'})}</div><div class="detail-row">${icon('clock')}${clock(b.start)}–${clock(b.end)} · ${b.end-b.start} min</div><div class="detail-row">${icon(b.location?'location':'book')}${esc(b.location||b.course||'Personal time')}</div>${!snapshot&&!b.hard?`${button('focus','Start a focus session','play','btn primary')}${button('lock',b.locked?'Unlock this block':'Keep this time','lock','btn')}<p class="detail-note">Locked blocks stay exactly here when the rest of your week changes.</p>`:b.hard?'<p class="detail-note">This commitment stays fixed. Any overlaps will be surfaced for you to resolve.</p>':''}</section>`;}
function taskRows(tasks){return tasks.map(t=>{const placed=plan.blocks.filter(b=>b.taskId===t.id).reduce((s,b)=>s+b.end-b.start,0);return `<div class="task-row ${t.done?'done':''}"><button class="task-check ${t.done?'done':''}" data-complete="${esc(t.id)}" aria-label="${t.done?'Reopen':'Complete'} ${esc(t.title)}" role="checkbox" aria-checked="${!!t.done}" ${snapshot?'disabled':''}>${t.done?icon('check'):''}</button><div class="task-content"><button class="task-name" data-edit="${esc(t.id)}" ${snapshot?'disabled':''}>${esc(t.title)}</button><div class="task-meta"><span class="course-label">${esc(t.course)}</span><span class="due-label">${formatDate(t.dueDate||addDays(week,Math.floor(t.due/1440)),{month:'short',day:'numeric'})} · ${timeLabel(t.dueTime??t.due%1440)}</span></div><div class="task-meta"><span>${t.minutes} min ${t.done?'· completed':t.overdue?'· overdue':t.upcoming?'· next week':'estimated'}</span><span>${t.done?'Done':placed>=t.minutes?'Scheduled':'Needs time'}</span></div><div class="task-effort" aria-hidden="true">${Array.from({length:Math.min(8,Math.ceil(t.minutes/25))},(_,i)=>`<i class="${t.done||i<Math.ceil(placed/25)?'on':''}"></i>`).join('')}</div></div></div>`}).join('');}
function taskPanel(){return `<section class="panel"><div class="panel-pad"><div class="panel-heading"><h3>On the horizon</h3><span class="pill outline">${weekTasks.filter(t=>!t.done).length} tasks</span></div>${taskRows([...weekTasks].sort((a,b)=>a.due-b.due).slice(0,4))||'<div class="empty" style="padding:20px 0"><p>Your deadlines will appear here.</p></div>'}</div>${snapshot?'':`<button class="panel-link" data-action="new-task"><span>＋ Add an assignment</span>${icon('arrow')}</button>`}</section>`;}
function conflictCard(count){const [a,b]=plan.conflicts[0]||[];return `<section class="conflict-card">${icon('alert')}<div><b>${count} ${count===1?'detail needs':'details need'} your attention</b><p>${a?`${esc(a.title)} overlaps ${esc(b.title)} on ${short[a.day]}.`:esc(plan.violations[0]?.note)}</p>${button('conflicts','Take a closer look','arrow','')}</div></section>`;}
function workloadChart(){const loads=days.map((_,i)=>({hard:hard.filter(b=>b.day===i).reduce((s,b)=>s+b.end-b.start,0),study:plan.blocks.filter(b=>!b.hard&&b.day===i).reduce((s,b)=>s+b.end-b.start,0)})),max=Math.max(1,...loads.map(x=>x.hard+x.study));return `<section class="panel panel-pad"><div class="panel-heading"><h3>Your weekly rhythm</h3>${icon('leaf')}</div><div class="workload-chart" aria-label="Daily fixed and study workload">${loads.map((x,i)=>`<div class="workload-col" title="${days[i]}: ${hours(x.hard)} hours fixed, ${hours(x.study)} hours study"><i class="study-bar" style="height:${x.study/max*60}px"></i><i class="hard-bar" style="height:${x.hard/max*60}px"></i></div>`).join('')}</div><div class="workload-labels">${short.map(d=>`<span>${d[0]}</span>`).join('')}</div><div class="workload-foot"><span>■ Commitments &nbsp; <span style="color:#8da876">■ Study</span></span><span>${hours(loads.reduce((s,x)=>s+x.hard+x.study,0))}h total</span></div></section>`;}
function tasksView(){const tasks=state.tasks.filter(t=>taskFilter==='all'||(taskFilter==='done'?t.done:!t.done)).sort((a,b)=>a.dueDate.localeCompare(b.dueDate)||a.dueTime-b.dueTime);return `<div class="page-toolbar"><div class="toggle">${['open','done','all'].map(t=>button('filter-'+t,{open:'To do',done:'Completed',all:'All assignments'}[t],null,taskFilter===t?'active':'')).join('')}</div><span class="sub">${tasks.length} assignments · ${hours(tasks.reduce((s,t)=>s+t.minutes,0))} hours estimated</span></div><div class="task-board"><div class="table-scroll"><div class="task-table-header"><span></span><span>Assignment</span><span>Course</span><span>Due</span><span>Effort</span><span>Status</span></div>${tasks.map(t=>`<div class="task-table-row ${t.done?'done':''}"><button class="task-check ${t.done?'done':''}" data-complete="${esc(t.id)}" aria-label="Complete ${esc(t.title)}">${t.done?icon('check'):''}</button><button class="task-name" data-edit="${esc(t.id)}">${esc(t.title)}</button><span class="course-label">${esc(t.course)}</span><small>${formatDate(t.dueDate,{month:'short',day:'numeric'})}<br>${timeLabel(t.dueTime)}</small><small>${t.minutes} min</small><span class="pill ${!t.done&&t.dueDate<today?'amber':''}">${t.done?'Complete':t.dueDate<today?'Overdue':'To do'}</span></div>`).join('')||'<div class="empty"><h2>A little breathing room.</h2><p>No assignments in this view.</p></div>'}</div></div>`;}
function sourcesView(){return `<div class="inline-notice">${icon('shield')}<span>This is your local workspace. Import files to replace the sample schedule. Live Canvas feeds and hosted accounts are not connected.</span></div><div class="page-grid">${[['matrix','shield','Cadetship matrix','Your formations, training, duties, and other fixed commitments.',state.hard.filter(b=>b.kind==='corps').length,'commitments','Upload CSV'],['canvas','calendar','Canvas assignments','Bring in assignment deadlines from a Canvas calendar export.',state.tasks.length,'assignments','Import .ics file']].map(([key,ico,title,desc,count,unit,cta])=>`<section class="wide-panel"><div class="source-top"><div class="source-icon">${icon(ico)}</div><span class="pill outline">${key==='matrix'?'01 / CORPS':'02 / DEADLINES'}</span></div><h2>${title}</h2><p>${desc}</p><div class="source-stats"><div class="source-stat"><b>${count}</b><span>${unit}</span></div><div class="source-stat"><b>Local</b><span>stored on this device</span></div></div><div class="source-file">${esc(state.sources[key])}</div><div class="source-actions">${button('upload-'+key,cta,'plus','btn primary')}${key==='matrix'?button('sample-download','Sample CSV','download','btn'):''}</div></section>`).join('')}<section class="wide-panel"><div class="source-top"><div class="source-icon">${icon('book')}</div><span class="pill outline">03 / ACADEMICS</span></div><h2>Your course sections</h2><p>${esc(state.sources.term)}. Choose your sections from the current local catalog.</p><div style="margin:18px 0">${[...new Set(state.catalog.map(b=>b.course))].map(c=>{const match=state.catalog.find(b=>b.course===c);return `<label class="section-option"><input type="checkbox" data-course="${esc(c)}" ${state.enrolled.includes(c)?'checked':''}><div><b>${esc(c)}</b><small>${esc(match.title)}</small></div><span class="pill outline">${state.catalog.filter(b=>b.course===c).length} / wk</span></label>`}).join('')}</div><div class="source-actions">${button('save-sections','Save sections','check','btn primary')}${button('upload-term','Import term CSV','plus','btn')}</div></section><section class="wide-panel"><div class="source-top"><div class="source-icon">${icon('archive')}</div><span class="pill outline">YOUR DATA</span></div><h2>A little peace of mind.</h2><p>Keep a portable copy of your assignments, preferences, saved plans, and source files. Restore it on this browser whenever you need.</p><div class="source-stats"><div class="source-stat"><b>${state.archive.length}</b><span>saved snapshots</span></div><div class="source-stat"><b>${state.uploads.length}</b><span>source imports</span></div></div><div class="source-actions">${button('backup','Download backup','download','btn primary')}${button('restore-backup','Restore backup','archive','btn')}</div><div class="source-file">Your files stay on this device.</div></section></div><input id="import-file" type="file" hidden>`;}
function prefsView(){return `<form id="prefs-form"><div class="page-grid"><section class="wide-panel"><div class="source-icon">${icon('sun')}</div><h2>Your daily rhythm</h2><p class="sub">Protect sleep and meals first. Study will fit around your daily rhythm.</p><div class="form-grid">${[['wake','Wake-up time'],['sleep','Bedtime']].map(([k,l])=>`<label class="field">${l}<input type="time" name="${k}" value="${clock(state.prefs[k])}" required></label>`).join('')}</div><div class="inline-notice" style="margin:15px 0 0">${icon('moon')}<span>${hours(1440-state.prefs.sleep+state.prefs.wake)} hours for rest. Protected every night.</span></div><h3 style="margin-top:24px">Meal windows</h3><div class="form-grid">${[['Lunch',0],['Dinner',1]].map(([label,i])=>`<label class="field">${label} starts<input type="time" name="meal-${i}-start" value="${clock((state.prefs.meals||[[720,780],[1080,1140]])[i][0])}" required></label><label class="field">${label} ends<input type="time" name="meal-${i}-end" value="${clock((state.prefs.meals||[[720,780],[1080,1140]])[i][1])}" required></label>`).join('')}</div><h3 style="margin-top:28px">How should your study feel?</h3><div class="radio-options"><label class="radio-card"><input type="radio" name="strategy" value="balanced" ${state.prefs.strategy==='balanced'?'checked':''}><span>Balanced<small>Spread the effort across your available days.</small></span></label><label class="radio-card"><input type="radio" name="strategy" value="early" ${state.prefs.strategy!=='balanced'?'checked':''}><span>Head start<small>Finish as early in the week as possible.</small></span></label></div></section><section class="wide-panel"><div class="source-icon">${icon('spark')}</div><h2>Focus, within reason</h2><p>Give your work enough room without filling every spare minute.</p><div class="form-grid">${[['minBlock','Smallest block',15,60,5],['maxBlock','Longest block',25,180,5],['maxDaily','Daily study limit',30,720,15],['buffer','Travel buffer',0,60,5],['lead','Finish ahead of deadline',0,72,1],['lookaheadDays','Look ahead to deadlines',0,7,1]].map(([k,l,min,max,step])=>`<label class="field">${l}<input name="${k}" type="number" min="${min}" max="${max}" step="${step}" value="${state.prefs[k]}" required><small>${k==='lead'?'hours':k==='lookaheadDays'?'days beyond the week':'minutes'}</small></label>`).join('')}</div></section><section class="wide-panel"><div class="source-icon">${icon('leaf')}</div><h2>Protect something for you.</h2><p>A workout, a quiet evening, or time to call home. Protected time stays fixed when you regenerate.</p><div style="margin:18px 0">${state.hard.filter(b=>b.source==='protected').map(b=>`<div class="section-option"><div><b>${esc(b.title)}</b><small>${days[b.day]} · ${clock(b.start)}–${clock(b.end)}</small></div><button class="icon-btn" data-remove-block="${esc(b.id)}" type="button" aria-label="Remove ${esc(b.title)}">${icon('close')}</button></div>`).join('')}</div>${button('protect','Protect a time block','plus','btn','type="button"')}</section></div><div class="page-toolbar" style="margin-top:22px"><span class="sub">Changes apply when you save.</span><button class="btn primary" type="submit">${icon('check')} Save preferences</button></div></form>`;}
function archiveView(){return state.archive.length?`<div class="page-grid">${state.archive.map((p,i)=>`<section class="wide-panel"><div class="archive-thumb" aria-hidden="true">${days.map((d,j)=>`<div>${p.plan.blocks.filter(b=>b.day===j).slice(0,6).map((b,k)=>`<i style="top:${k*14}px"></i>`).join('')}</div>`).join('')}</div><span class="eyebrow">WEEKLY SNAPSHOT</span><h2>${esc(p.date)}</h2><p>${p.plan.blocks.length} blocks · ${p.plan.conflicts.length} conflicts</p><div class="archive-meta"><span>${esc(p.created)}</span><button class="text-btn" data-snapshot="${i}">Open plan ${icon('arrow')}</button></div></section>`).join('')}</div>`:`<section class="wide-panel empty">${icon('archive')}<h2>Good weeks are worth keeping.</h2><p>Save a snapshot from My week. Your schedule and deadlines will be preserved exactly as they are.</p>${button('go-week','Back to my week','arrow','btn','style="margin-top:22px"')}</section>`;}
function printView(){return `<div class="print-only"><section class="print-page"><h2>${range()} · Weekly schedule</h2><table class="print-grid"><thead><tr><th>Time</th>${short.map(d=>`<th>${d}</th>`).join('')}</tr></thead><tbody>${Array.from({length:34},(_,i)=>{const start=360+i*30;return `<tr><td>${clock(start)}</td>${days.map((d,j)=>`<td>${plan.blocks.filter(b=>b.day===j&&b.start<start+30&&b.end>start).map(b=>`<div class="${b.hard?'':'print-study'}"><b>${esc(b.title)}</b></div>`).join('')}</td>`).join('')}</tr>`}).join('')}</tbody></table></section><section class="print-page"><h2>Daily agenda · ${range()}</h2><div class="print-agenda">${days.map((d,i)=>`<div class="print-day"><h3>${d}</h3>${plan.blocks.filter(b=>b.day===i).sort((a,b)=>a.start-b.start).map(b=>`<p>☐ ${clock(b.start)}–${clock(b.end)} ${esc(b.title)}</p>`).join('')}</div>`).join('')}</div></section><section class="print-page"><h2>Deadlines & loose ends</h2><table class="print-deadlines"><thead><tr><th>Assignment</th><th>Course</th><th>Due</th><th>Effort</th><th>Status</th></tr></thead><tbody>${weekTasks.map(t=>`<tr><td>${esc(t.title)}</td><td>${esc(t.course)}</td><td>${formatDate(t.dueDate||addDays(week,Math.floor(t.due/1440)),{month:'short',day:'numeric'})} ${clock(t.dueTime??t.due%1440)}</td><td>${t.minutes} min</td><td>${t.done?'Complete':plan.unplaced.some(x=>x.taskId===t.id)?'Needs room':'Scheduled'}</td></tr>`).join('')}</tbody></table><div class="print-conflicts"><h3>Conflicts & unplaced work</h3>${plan.conflicts.map(([a,b])=>`<p>${days[a.day]}: ${esc(a.title)} overlaps ${esc(b.title)}.</p>`).join('')}${(plan.violations||[]).map(v=>`<p>${esc(v.note)}</p>`).join('')}${plan.unplaced.map(u=>`<p>${esc(u.title)}: ${u.minutes} minutes still need a place.</p>`).join('')}</div></section></div>`;}
function modal(title,body,cls=''){const d=$('#modal');d.className=cls;d.setAttribute('aria-labelledby','modal-title');d.innerHTML=`<div class="dialog-header"><h2 id="modal-title">${title}</h2>${button('close-modal','','close','icon-btn','aria-label="Close dialog"')}</div>${body}`;if(!d.open)d.showModal();}
function error(message){const el=$('#form-error');if(el)el.textContent=message;else notify(message);}
function taskModal(id){if(snapshot)return;const t=state.tasks.find(t=>t.id===id);modal(t?'A little fine-tuning.':'Make room for what’s next.',`<p class="sub">Set the deadline. We’ll find time for the work.</p><form id="task-form"><label class="field">Assignment<input name="title" placeholder="What do you need to get done?" value="${esc(t?.title||'')}" maxlength="160" required autofocus></label><div class="form-grid"><label class="field">Course<input name="course" placeholder="e.g. ERH-101" value="${esc(t?.course||'')}" maxlength="40" required></label><label class="field">Estimated effort<input name="minutes" type="number" min="15" max="2400" step="5" value="${t?.minutes||60}" required><small>minutes · you can change this anytime</small></label><label class="field">Due date<input name="date" type="date" value="${t?.dueDate||addDays(week,selectedDay)}" required></label><label class="field">Due time<input name="time" type="time" value="${clock(t?.dueTime??1439)}" required></label></div><label class="field">A note for yourself<textarea name="notes" placeholder="The first step, a useful reference, or a reminder.">${esc(t?.notes||'')}</textarea></label><div id="form-error" class="dialog-error" role="alert"></div><div class="dialog-actions">${t?button('delete-task','Remove assignment',null,'text-btn delete',`type="button" data-task-id="${esc(t.id)}"`):''}${button('close-modal','Cancel',null,'btn ghost','type="button"')}<button class="btn primary" type="submit">${icon('check')} ${t?'Save changes':'Add to my week'}</button></div></form>`);$('#task-form').onsubmit=e=>{e.preventDefault();try{const f=new FormData(e.target),next={...t,id:t?.id||crypto.randomUUID(),title:f.get('title').trim(),course:f.get('course').trim(),minutes:Number(f.get('minutes')),dueDate:f.get('date'),dueTime:parseTime(f.get('time')),notes:f.get('notes').trim(),done:t?.done||false};if(!next.title||!next.course)throw Error('Add an assignment title and course.');if(t)state.tasks=state.tasks.map(x=>x.id===t.id?next:x);else state.tasks.push(next);if(t&&(t.minutes!==next.minutes||t.dueDate!==next.dueDate||t.dueTime!==next.dueTime))state.locked=state.locked.filter(b=>b.taskId!==t.id);$('#modal').close();update(t?'Assignment updated. Changed estimates and deadlines have been replanned.':'Assignment added to your plan.');}catch(err){error(err.message)}};}
function protectModal(){modal('Keep a little time for you.',`<p class="sub">This time stays yours when the week is regenerated.</p><form id="protect-form"><label class="field">What’s this time for?<input name="title" placeholder="Gym, a walk, call home…" required></label><label class="field">Day<select name="day">${days.map((d,i)=>`<option value="${i}" ${i===selectedDay?'selected':''}>${d}</option>`).join('')}</select></label><div class="form-grid"><label class="field">Starts<input type="time" name="start" value="18:00" required></label><label class="field">Ends<input type="time" name="end" value="19:00" required></label></div><label class="field">Repeat<select name="scope"><option value="week">This week only</option><option value="standing">Every week</option></select></label><div id="form-error" class="dialog-error"></div><div class="dialog-actions"><button type="submit" class="btn primary">${icon('lock')} Protect this time</button></div></form>`);$('#protect-form').onsubmit=e=>{e.preventDefault();try{const f=new FormData(e.target),start=parseTime(f.get('start')),end=parseTime(f.get('end'));if(start>=end)throw Error('Choose an end time after the start.');state.hard.push({id:crypto.randomUUID(),title:f.get('title').trim(),day:Number(f.get('day')),start,end,week:f.get('scope')==='week'?week:null,kind:'personal',source:'protected',hard:true});$('#modal').close();update('Your time is protected.');}catch(err){error(err.message)}};}
function conflictModal(){modal('A few loose ends.',`<p class="sub">Fixed commitments and locks are never silently moved.</p>${plan.conflicts.map(([a,b])=>`<div class="conflict-card" style="margin-top:15px">${icon('alert')}<div><b>${days[a.day]} · ${clock(Math.max(a.start,b.start))}–${clock(Math.min(a.end,b.end))}</b><p>${esc(a.title)}<br>${esc(b.title)}</p><p>Check the commitment with your instructor or unit.</p></div></div>`).join('')}${(plan.violations||[]).map(v=>`<div class="inline-notice" style="margin-top:15px">${esc(v.note)}</div>`).join('')}${plan.unplaced.map(u=>`<div class="section-option"><div><b>${esc(u.title)}</b><small>${u.minutes} minutes unplaced · ${esc(u.reason)}</small></div></div>`).join('')}<div class="dialog-actions">${button('close-modal','Got it','check','btn primary')}</div>`);}
function focusModal(){
 const block=plan.blocks.find(b=>b.id===selected),task=state.tasks.find(t=>t.id===block?.taskId)||weekTasks.find(t=>!t.done);
 if(!timer){if(!task)return notify('Add an assignment to start a focus session.');timer={id:crypto.randomUUID(),taskId:task.id,title:task.title,total:1500,remaining:1500,running:false,createdAt:Date.now()};saveFocus();}
 timer.remaining=focusRemaining(timer);const display=String(Math.floor(timer.remaining/60)).padStart(2,'0')+':'+String(timer.remaining%60).padStart(2,'0');
 modal('A LITTLE SPACE TO FOCUS',`<div class="focus-task">${esc(timer.title)}</div><div class="toggle"><button data-duration="25" class="${timer.total===1500?'active':''}" ${timer.running?'disabled':''}>25 min</button><button data-duration="50" class="${timer.total===3000?'active':''}" ${timer.running?'disabled':''}>50 min</button></div><div class="focus-time" id="focus-time" role="timer" aria-live="off">${display}</div><p>One task. One quiet stretch of time.<br>Your session keeps going when you close this panel.</p><div class="focus-controls">${button('timer-toggle',timer.remaining===0?'Session finished':timer.running?'Pause':'Begin focus',timer.running?'pause':'play','btn lime',timer.remaining===0?'disabled':'')}${button('timer-reset','Reset',null,'btn ghost','style="color:#a5b590"')}</div><div class="focus-end-actions">${button('finish-focus','Finish & log time','check','text-btn')}${button('complete-focus','Complete assignment','tasks','text-btn')}</div>`,'focus-dialog');
}
function saveFocus(){state.focusSession=timer?{...timer}:null;persist();}
function renderFocusDock(){let dock=$('#focus-dock');if(!dock){dock=document.createElement('div');dock.id='focus-dock';document.body.append(dock);}if(!timer){dock.innerHTML='';return;}const remaining=focusRemaining(timer),time=String(Math.floor(remaining/60)).padStart(2,'0')+':'+String(remaining%60).padStart(2,'0');dock.innerHTML=`<button class="focus-dock" data-action="resume-focus" aria-label="Open focus session"><span class="focus-dot ${timer.running?'active':''}">${icon(timer.running?'pause':'play')}</span><span><b>${remaining===0?'Session finished':timer.running?'Focus in progress':'Focus paused'}</b><small>${esc(timer.title)}</small></span><time>${time}</time></button>`;}
function endFocus(markComplete=false){if(!timer)return;timer.remaining=focusRemaining(timer);const minutes=Math.floor((timer.total-timer.remaining)/60),id=timer.taskId;if(minutes>0){state.sessions=state.sessions||[];if(!state.sessions.some(s=>s.id===timer.id))state.sessions.push({id:timer.id,taskId:id,title:timer.title,minutes,finishedAt:new Date().toISOString()});}clearInterval(timerInterval);timer=null;saveFocus();$('#modal').close();if(markComplete){const task=state.tasks.find(t=>t.id===id);if(task&&!task.done){toggleDone(id);return;}}renderFocusDock();notify(minutes?minutes+' minutes of focus logged.':'Focus session finished.');}
function tick(){
 if(!timer)return;timer.remaining=focusRemaining(timer);const display=String(Math.floor(timer.remaining/60)).padStart(2,'0')+':'+String(timer.remaining%60).padStart(2,'0');if($('#focus-time'))$('#focus-time').textContent=display;
 if(timer.running&&timer.remaining===0){timer.running=false;clearInterval(timerInterval);saveFocus();const control=$('[data-action="timer-toggle"]');if(control){control.disabled=true;control.innerHTML=icon('check')+'<span>Session finished</span>';}notify('Focus session complete. Log your time when you are ready.');}renderFocusDock();
}
function searchModal(){modal('Quick find',`<input class="command-input" id="command" autocomplete="off" placeholder="Find an assignment or jump somewhere…" aria-label="Search"><div class="command-list" id="command-list"></div>`);const fill=()=>{const q=$('#command').value.toLowerCase();$('#command-list').innerHTML=[...navItems.filter(n=>n[2].toLowerCase().includes(q)).map(([id,ico,label])=>`<button class="command-item" data-view="${id}"><span>${icon(ico)}${label}</span><small>Open page</small></button>`),...state.tasks.filter(t=>t.title.toLowerCase().includes(q)||t.course.toLowerCase().includes(q)).slice(0,6).map(t=>`<button class="command-item" data-edit="${esc(t.id)}"><span>${icon('tasks')}${esc(t.title)}</span><small>${esc(t.course)}</small></button>`)].join('')||'<div class="empty"><p>No matches yet.</p></div>';};fill();$('#command').oninput=()=>{fill();commandIndex=-1;};let commandIndex=-1;$('#command').onkeydown=e=>{const items=$$('.command-item');if(['ArrowDown','ArrowUp'].includes(e.key)){e.preventDefault();commandIndex=(commandIndex+(e.key==='ArrowDown'?1:-1)+items.length)%items.length;items.forEach((item,i)=>item.classList.toggle('is-active',i===commandIndex));items[commandIndex]?.scrollIntoView({block:'nearest'});}if(e.key==='Enter'){e.preventDefault();items[Math.max(0,commandIndex)]?.click();}};$('#command').focus();}
function download(name,data,type='application/json'){const url=URL.createObjectURL(new Blob([data],{type})),a=document.createElement('a');a.href=url;a.download=name;a.click();setTimeout(()=>URL.revokeObjectURL(url),1000);}
function setWeek(key){week=key;snapshot=null;selected=null;selectedDay=Math.max(0,Math.min(6,dayDiff(today,week)));refresh();render();}
function toggleDone(id){if(snapshot)return;const t=state.tasks.find(t=>t.id===id);if(!t)return;t.done=!t.done;state.locked=state.locked.filter(b=>b.taskId!==id);update(t.done?'One less thing on your mind. Assignment completed.':'Assignment reopened.');}
document.addEventListener('click',async e=>{
 const el=e.target.closest('button');if(!el)return;
 if(el.dataset.view){if($('#modal').open)$('#modal').close();view=el.dataset.view;snapshot=null;selected=null;refresh();render();return;}
 if(el.dataset.date){view='week';setWeek(monday(el.dataset.date));return;}
 if(el.dataset.day!==undefined){selectedDay=Number(el.dataset.day);render();return;}
 if(el.dataset.filter){filter.has(el.dataset.filter)?filter.delete(el.dataset.filter):filter.add(el.dataset.filter);render();return;}
 if(el.dataset.block){selected=selected===el.dataset.block?null:el.dataset.block;render();if(window.innerWidth<850)document.querySelector('.cockpit').scrollIntoView({behavior:'smooth',block:'start'});return;}
 if(el.dataset.edit){taskModal(el.dataset.edit);return;}
 if(el.dataset.complete){toggleDone(el.dataset.complete);return;}
 if(el.dataset.snapshot!==undefined){const p=state.archive[Number(el.dataset.snapshot)];snapshot=structuredClone(p);week=p.week||'2026-09-14';snapshot.tasks=(p.tasks||[]).map(t=>({...t,dueDate:t.dueDate||addDays(week,Math.floor(t.due/1440)),dueTime:t.dueTime??t.due%1440}));view='week';selected=null;refresh();render();return;}
 if(el.dataset.removeBlock){const b=state.hard.find(b=>b.id===el.dataset.removeBlock);state.hard=state.hard.filter(b=>b.id!==el.dataset.removeBlock);update('Protected time removed.');notify('Protected time removed.',()=>{state.hard.push(b);update('Protected time restored.');});return;}
 if(el.dataset.duration){if(!timer||timer.running)return;timer.total=Number(el.dataset.duration)*60;timer.remaining=timer.total;timer.id=crypto.randomUUID();clearInterval(timerInterval);saveFocus();focusModal();renderFocusDock();return;}
 const action=el.dataset.action;if(!action)return;
 if(action==='undo'){const fn=undo;undo=null;fn?.();return;}
 if(action==='close-modal'){$('#modal').close();return;}
 if(action==='new-task'){taskModal();return;}
 if(action==='search'){searchModal();return;}
 if(action==='close-detail'){selected=null;render();return;}
 if(action==='week-layout'||action==='agenda-layout'){layout=action==='week-layout'?'week':'agenda';render();return;}
 if(action==='prev'||action==='next'){setWeek(addDays(week,action==='prev'?-7:7));return;}
 if(action==='today'){setWeek(monday());return;}
 if(action==='go-week'){view='week';render();return;}
 if(action==='exit-snapshot'){snapshot=null;refresh();render();return;}
 if(action==='regenerate'){el.disabled=true;el.innerHTML=icon('spark','spinning')+'<span>Finding your rhythm…</span>';await new Promise(r=>setTimeout(r,450));update('Your week is ready. Locked blocks stayed in place.');return;}
 if(action==='download-pdf'){el.disabled=true;el.innerHTML=icon('download')+'<span>Preparing PDF…</span>';try{const bytes=await createPlanPDF({week,plan,tasks:weekTasks});download(`palette-${week}.pdf`,bytes,'application/pdf');$('#modal').close();notify('Your printable week is ready.');}catch(err){notify('PDF export failed. You can still use browser print.');el.disabled=false;el.textContent='Try PDF again';}return;}
 if(action==='print'){modal('Take your week with you.',`<p class="sub" style="margin-top:16px">A weekly grid, a daily checklist, and your deadlines. Formatted for Letter landscape.</p><div class="source-stats"><div class="source-stat"><b>01</b><span>Weekly overview</span></div><div class="source-stat"><b>02</b><span>Daily agenda</span></div><div class="source-stat"><b>03</b><span>Deadlines</span></div></div><p class="sub">Download a ready-to-print PDF that works offline. A busy schedule may use extra pages to keep every detail readable.</p><div class="dialog-actions">${button('do-print','Browser print','print','btn')}${button('download-pdf','Download PDF','download','btn primary')}</div>`);return;}
 if(action==='do-print'){$('#modal').close();window.print();return;}
 if(action==='save-plan'){state.archive.unshift({id:crypto.randomUUID(),week,date:range(),created:new Date().toLocaleString(),plan:structuredClone(plan),tasks:structuredClone(weekTasks),hard:structuredClone(hard),prefs:structuredClone(state.prefs)});persist();notify('This week is safely tucked in your archive.');return;}
 if(action==='lock'){const b=plan.blocks.find(b=>b.id===selected);if(!b||b.hard||snapshot)return;state.locked=b.locked?state.locked.filter(x=>!(x.id===b.id&&x.week===week)):[...state.locked,{...b,week,locked:true}];update(b.locked?'This block is flexible again.':'This time is yours to keep. Block locked.');return;}
 if(action==='focus'||action==='resume-focus'){focusModal();return;}
 if(action==='finish-focus'){endFocus(false);return;}
 if(action==='day-agenda'){layout='agenda';render();return;}
 if(action==='timer-toggle'){if(!timer||focusRemaining(timer)===0)return;timer.remaining=focusRemaining(timer);timer.running=!timer.running;clearInterval(timerInterval);if(timer.running){timer.end=Date.now()+timer.remaining*1000;timerInterval=setInterval(tick,1000);}saveFocus();focusModal();renderFocusDock();return;}
 if(action==='timer-reset'){clearInterval(timerInterval);timer.running=false;timer.remaining=timer.total;timer.id=crypto.randomUUID();saveFocus();focusModal();renderFocusDock();return;}
 if(action==='complete-focus'){endFocus(true);return;}
 if(action==='conflicts'){conflictModal();return;}
 if(action.startsWith('filter-')){taskFilter=action.slice(7);render();return;}
 if(action==='protect'){protectModal();return;}
 if(action==='delete-task'){const id=el.dataset.taskId,t=state.tasks.find(t=>t.id===id),locks=state.locked.filter(b=>b.taskId===id);state.tasks=state.tasks.filter(t=>t.id!==id);state.locked=state.locked.filter(b=>b.taskId!==id);$('#modal').close();update();notify('Assignment removed.',()=>{state.tasks.push(t);state.locked.push(...locks);update('Assignment restored.');});return;}
 if(action==='save-sections'){state.enrolled=$$('[data-course]:checked').map(el=>el.dataset.course);state.hard=state.hard.filter(b=>b.kind!=='class').concat(state.catalog.filter(b=>state.enrolled.includes(b.course)));update('Course sections saved. Your week has been updated.');return;}
 if(action==='sample-download'){download('palette-sample-matrix.csv','Day,Start,End,Activity,Location,Uniform\nMonday,0700,0730,BRC Formation,Old Barracks,Class B\nWednesday,1530,1630,MAC Training,Parade Ground,\nFriday,1600,1700,Friday Parade,Parade Ground,','text/csv');return;}
 if(action==='backup'){download('palette-backup-'+today+'.json',JSON.stringify(state,null,2));return;}
 if(action.startsWith('upload-')||action==='restore-backup'){const kind=action==='restore-backup'?'backup':action.slice(7),input=$('#import-file');input.accept=kind==='canvas'?'.ics':kind==='backup'?'.json':'.csv';input.value='';input.onchange=async()=>{if(input.files[0])await importFile(kind,input.files[0]);};input.click();return;}
});
document.addEventListener('submit',e=>{if(e.target.id!=='prefs-form')return;e.preventDefault();const f=new FormData(e.target),next={...state.prefs};try{for(const k of ['wake','sleep'])next[k]=parseTime(f.get(k));for(const k of ['minBlock','maxBlock','maxDaily','buffer','lead','lookaheadDays'])next[k]=Number(f.get(k));next.strategy=f.get('strategy');next.meals=[0,1].map(i=>[parseTime(f.get(`meal-${i}-start`)),parseTime(f.get(`meal-${i}-end`))]);if(next.meals.some(([start,end])=>start>=end))throw Error('Meal windows must end after they start.');if(next.sleep<=next.wake)throw Error('Bedtime must come after wake-up time.');if(next.minBlock>next.maxBlock)throw Error('Your smallest block must be shorter than your longest block.');state.prefs=next;update('Your boundaries are saved. The week has been replanned.');}catch(err){notify(err.message);}});
document.addEventListener('keydown',e=>{if((e.ctrlKey||e.metaKey)&&e.key.toLowerCase()==='k'&&!$('#modal').open){e.preventDefault();searchModal();}else if(e.key==='n'&&!$('#modal').open&&!/INPUT|TEXTAREA|SELECT/.test(e.target.tagName)){e.preventDefault();taskModal();}});
$('#modal').addEventListener('close',()=>{saveFocus();renderFocusDock();});
async function importFile(kind,file){try{const raw=await file.text();if(kind==='backup'){const next=validateBackup(JSON.parse(raw));modal('Restore your workspace?',`<p class="sub">This backup contains ${next.tasks.length} assignments, ${next.hard.length} commitments, and ${next.archive?.length||0} saved plans. Your current workspace will be replaced.</p><div class="dialog-actions">${button('close-modal','Cancel',null,'btn ghost')}<button id="confirm-import" class="btn primary">Restore backup</button></div>`);$('#confirm-import').onclick=()=>{const before=structuredClone(state);const applyBackup=data=>{clearInterval(timerInterval);Object.assign(state,data);timer=state.focusSession||null;if(timer?.running){tick();timerInterval=setInterval(tick,1000);}update();};$('#modal').close();applyBackup(next);notify('Workspace restored.',()=>{applyBackup(before);notify('Previous workspace restored.');});};return;}
 if(kind==='matrix'){const detected=detectMatrix(parseCSV(raw)),fingerprint=detected.headers.map(h=>h.toLowerCase()).join('|'),remembered=state.mappings[fingerprint];modal('Bring in your commitments.',`<p class="sub">${esc(file.name)} · ${detected.wide?'Day-column grid':'Event list'} · ${detected.rows.length} rows</p><div style="overflow:auto"><table class="preview-table"><thead><tr>${detected.headers.map(h=>`<th>${esc(h)}</th>`).join('')}</tr></thead><tbody>${detected.rows.slice(0,3).map(r=>`<tr>${r.map(v=>`<td>${esc(v)}</td>`).join('')}</tr>`).join('')}</tbody></table></div>${detected.wide?'':`<div class="form-grid">${[['day','Day'],['start','Start time'],['end','End time'],['title','Activity']].map(([k,l])=>`<label class="field">${l}<select id="map-${k}">${detected.headers.map((h,i)=>`<option value="${i}" ${remembered?remembered[k]===i?'selected':'':new RegExp(k==='title'?'activity|title|event':k,'i').test(h)?'selected':''}>${esc(h)}</option>`).join('')}</select></label>`).join('')}</div>`}<label class="field">This schedule applies to<select id="matrix-scope"><option value="standing">Every week</option><option value="week">${range()} only</option></select></label><p class="sub">${remembered?'Your saved column mapping is selected. ':''}This replaces the corps commitments for the chosen scope.</p><div id="form-error" class="dialog-error"></div><div class="dialog-actions"><button id="confirm-import" class="btn primary">Confirm and import</button></div>`);$('#confirm-import').onclick=()=>{try{const mapping=detected.wide?null:Object.fromEntries(['day','start','end','title'].map(k=>[k,Number($('#map-'+k).value)])),scope=$('#matrix-scope').value,events=parseMatrix(detected,mapping,scope==='week'?week:null);if(!events.length)throw Error('No commitments were found. Check the columns and times.');const before=structuredClone(state.hard),oldOverrides=[...(state.matrixWeekOverrides||[])],oldSource=state.sources.matrix;if(scope==='standing')state.hard=state.hard.filter(b=>b.kind!=='corps'||b.week);else {state.hard=state.hard.filter(b=>b.kind!=='corps'||b.week!==week);state.matrixWeekOverrides=state.matrixWeekOverrides||[];if(!state.matrixWeekOverrides.includes(week))state.matrixWeekOverrides.push(week);}state.hard.push(...events);if(mapping)state.mappings[fingerprint]=mapping;state.sources.matrix=file.name;if(!state.uploads.some(u=>u.kind===kind&&u.raw===raw))state.uploads.push({kind,name:file.name,raw,at:new Date().toISOString()});$('#modal').close();update();notify(`${events.length} commitments imported.`,()=>{state.hard=before;state.matrixWeekOverrides=oldOverrides;state.sources.matrix=oldSource;update('Previous commitments restored.');});}catch(err){error(err.message)}};return;}
 const parsed=kind==='term'?{events:parseTerm(parseCSV(raw)),warnings:[]}:parseCalendar(raw),items=parsed.events;
 if(!items.length)throw Error(parsed.warnings?.join(' ')||'No valid entries found in this file.');modal(kind==='term'?'Your term, all together.':'Your deadlines, brought in.',`<p class="sub">${esc(file.name)} · ${items.length} ${kind==='term'?'class meetings':'assignments'} ready to import.</p><div style="margin-top:20px">${items.slice(0,5).map(x=>`<div class="section-option"><div><b>${esc(x.title)}</b><small>${esc(x.course)} · ${kind==='term'?days[x.day]+' '+clock(x.start):formatDate(x.dueDate)+' '+clock(x.dueTime)}</small></div></div>`).join('')}</div>${parsed.warnings?.length?`<p class="dialog-error">${esc(parsed.warnings.join(' '))}</p>`:''}<p class="sub" style="margin-top:14px">${kind==='term'?'This becomes your local course catalog. All imported sections are selected initially.':'Matching calendar assignments update by their calendar ID. Your effort estimates stay yours.'}</p><div class="dialog-actions"><button id="confirm-import" class="btn primary">Import ${items.length} entries</button></div>`);$('#confirm-import').onclick=()=>{if(kind==='term'){state.catalog=items;state.enrolled=[...new Set(items.map(b=>b.course))];state.hard=state.hard.filter(b=>b.kind!=='class').concat(items);state.sources.term=file.name;}else{for(const t of items){const existing=state.tasks.find(x=>x.id===t.id);state.tasks=state.tasks.filter(x=>x.id!==t.id).concat({...t,minutes:existing?.minutes||60,done:existing?.done||false,notes:existing?.notes||''});if(existing&&(existing.dueDate!==t.dueDate||existing.dueTime!==t.dueTime))state.locked=state.locked.filter(b=>b.taskId!==t.id);}state.sources.canvas=file.name;}if(!state.uploads.some(u=>u.kind===kind&&u.raw===raw))state.uploads.push({kind,name:file.name,raw,at:new Date().toISOString()});$('#modal').close();update(`${items.length} entries imported.`);};
 }catch(err){notify(err.message||'The import could not be read.');}}

function weekContext(){
 if(snapshot)return '';
 if(addDays(week,7)<=today)return '<div class="week-brief"><div><b>A past week</b><small>Open a saved snapshot for the original schedule. New study is only placed in future time.</small></div></div>';
 const blocks=plan.blocks.filter(b=>b.day===selectedDay),focus=blocks.filter(b=>!b.hard),overdue=weekTasks.filter(t=>t.overdue).length,upcoming=weekTasks.filter(t=>t.upcoming).length;
 return `<div class="week-brief"><div class="brief-date"><b>${Number(addDays(week,selectedDay).slice(-2))}</b><span>${short[selectedDay].toUpperCase()}</span></div><div class="brief-copy"><b>${blocks.length} blocks. ${hours(focus.reduce((s,b)=>s+b.end-b.start,0))} hours to focus.</b><small>${overdue?overdue+' overdue to review':upcoming?upcoming+' upcoming deadlines included':'Your commitments and study, in one place.'}</small></div>${button('protect','Protect time','leaf','btn small')}${button('new-task','','plus','icon-btn','aria-label="Add assignment"')}</div>`;
}

refresh();render();persist();if(timer?.running){tick();timerInterval=setInterval(tick,1000);}
